  {
    "id": "[9]",
    "speaker_to_listener": "Milly→Michelle",
    "self_ref": "tôi",
    "addr_ref": "cô",
    "dst": "“Cô Michelle đó đến biệt viện này có việc gì thế? Nơi này đáng lẽ ra là cấm những người không được phép bén mảng đến cơ mà?”"
  },
  {
    "id": "[10]",
    "speaker_to_listener": "Michelle→Milly",
    "self_ref": "tôi",
    "addr_ref": "cô",
    "dst": "“Quả thực là vậy nhưng…… chẳng phải bên phía các cô mới là kẻ phá vỡ quy định trước sao?”"
