    "speaker_to_listener": "Michelle→Milly",
    "self_ref": "tôi",
    "addr_ref": "cô",
    "dst": "“Xin đừng cảnh giác như thế. Tôi chỉ có chút chuyện muốn nói với Rion-sama thôi.”"
