  {
    "id": "[13]",
    "speaker_to_listener": "Milly→Michelle",
    "self_ref": "tôi",
    "addr_ref": "cô",
    "dst": "“Như tôi vừa nói, đây không phải là nơi để những kẻ không có phận sự bước vào. Xin cô hãy rời cho.”"
  },
  {
    "id": "[14]",
    "speaker_to_listener": "Rion→Milly",
    "self_ref": "tớ",
    "addr_ref": "Milly",
    "dst": "——Milly, đợi đã."
  },
  {
    "id": "[15]",
    "dst": "Tôi đứng dậy khỏi ghế và kéo tay áo Milly."
