  {
    "id": "[16]",
    "speaker_to_listener": "Milly→Rion",
    "self_ref": "tôi",
    "addr_ref": "cậu chủ",
    "dst": "“……Rion-sama?”"
  },
  {
    "id": "[17]",
    "speaker_to_listener": "Rion→Milly",
    "self_ref": "tớ",
    "addr_ref": "Milly",
    "dst": "“Xin lỗi nhé, Milly. Tớ muốn nói chuyện với người đó một chút.”"
  },
  {
    "id": "[18]",
    "speaker_to_listener": "Milly→Rion",
    "self_ref": "tôi",
    "addr_ref": "cậu chủ",
    "dst": "“Nhưng mà…… Vâng, tôi hiểu rồi. Nếu Rion-sama đã quyết định vậy thì tôi sẽ không nói gì thêm nữa.”"
  },
  {
    "id": "[19]",
    "dst": "Vì Milly đã lùi sang một bên đứng chờ, tôi liền đối mặt với nữ hầu tự xưng là Michelle."
  },
  {
    "id": "[20]",
    "speaker_to_listener": "Michelle→Rion",
    "self_ref": "tôi",
    "addr_ref": "ngài",
    "dst": "“Ngài là Rion-sama phải không ạ?”"
  },
  {
    "id": "[21]",
    "speaker_to_listener": "Rion→Michelle",
    "self_ref": "tớ",
    "addr_ref": "cô",
    "dst": "“Ừ đúng rồi. Nghe nói cô là hầu gái hầu cận Crealydil-san, thế cô tìm tớ có chuyện gì thế?”"
  },
  {
    "id": "[22]",
    "dst": "Chừng nào kẻ xông vào biệt viện này không phải là người của Caroline-san, thì chắc chắn tình hình chưa đến mức tồi tệ nhất…… nhưng Michelle đang che giấu đủ loại cảm xúc khiến tôi không tài nào đoán được mục đích của cô ta."
  },
  {
    "id": "[23]",
    "dst": "Tôi chuẩn bị tinh thần để dù có phải nghe chuyện gì đi nữa cũng sẽ không bị dao động."
  },
  {
    "id": "[24]",
    "speaker_to_listener": "Michelle→Rion",
    "self_ref": "tôi",
    "addr_ref": "ngài",
    "dst": "“Trước khi truyền đạt lại công chuyện, tôi có thể hỏi ngài một câu được không ạ?”"
  },
  {
    "id": "[25]",
    "speaker_to_listener": "Rion→Michelle",
    "self_ref": "tớ",
    "addr_ref": "cô",
    "dst": "“Được chứ…… chuyện gì vậy?”"
  },
  {
    "id": "[26]",
    "speaker_to_listener": "Michelle→Rion",
    "self_ref": "tôi",
    "addr_ref": "ngài",
    "dst": "“Ngài có hứng thú với sự giao hợp giữa chị em ruột không ạ?”"
  },
  {
    "id": "[27]",
    "speaker_to_listener": "Rion→Michelle",
    "self_ref": "tớ",
    "addr_ref": "cô",
    "dst": "“……………………………Hả? Xin lỗi, chắc là tớ nghe nhầm rồi, cô nói lại lần nữa xem nào?”"
  },
  {
    "id": "[28]",
    "speaker_to_listener": "Michelle→Rion",
    "self_ref": "tôi",
    "addr_ref": "ngài",
    "dst": "“Ý tôi là, ngài có hứng thú với sự giao hợp giữa chị em ruột không ạ?”"
  },
  {
    "id": "[29]",
    "speaker_to_listener": "Rion→Michelle",
    "self_ref": "tớ",
    "addr_ref": "cô",
    "dst": "“Cái quái gì mà chẳng hiểu nổi thế hả!?”"
  },
  {
    "id": "[30]",
    "speaker_to_listener": "Michelle→Rion",
    "self_ref": "tôi",
    "addr_ref": "ngài",
    "dst": "“Giao hợp giữa chị em chính là việc chị và em trai có quan hệ tình dục—”"
  }
]

[
  {
    "id": "[1]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Ừm, cảm ơn em vì đã lo lắng nhé. Dạo này trời bắt đầu trở lạnh rồi, chắc là chị bị cảm mạo hay sao ấy nhỉ? Không hiểu sao hình như ở lãnh địa cũng đang lây lan dịch này nữa.”"
  },
  {
    "id": "[2]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Bị cảm thì không sao chứ… mùa đông ở vùng này có vẻ hanh khô, nhỡ mà là cúm hay gì thì đáng sợ lắm nên chị phải cẩn thận đấy nhé?”"
  },
  {
    "id": "[3]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“…Cúm là gì thế?”"
  },
  {
    "id": "[4]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“À thì… có thể coi là một dạng cảm mạo với các triệu chứng nặng ấy nhỉ?”"
  },
  {
    "id": "[5]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Hả, có thứ đó cơ à?”"
  },
  {
    "id": "[6]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Ừ. Thế nên lúc đi ngủ, chị treo khăn ẩm hay gì đó trong phòng là tốt nhất đấy.”"
  },
  {
    "id": "[7]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Thế á? Quả nhiên em trai chị hiểu biết rộng thật đấy. Ngay tối nay chị sẽ thử luôn, cảm ơn em nhé.”"
  },
  {
    "id": "[8]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Ừ. Thế thì tốt quá… Mà này chị Crealydil. Dạo này chị hay sang đây thế, cứ sang mãi thế này không khéo bị phát hiện đấy chứ?”"
  },
  {
    "id": "[9]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Hửm~? À, mẹ thì không sao đâu. Dạo này mẹ toàn mải đi tìm đối tượng kết hôn cho chị thôi.”"
  },
  {
    "id": "[10]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“…Như thế mà coi là không sao được à?”"
  },
  {
    "id": "[11]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Không tốt lắm đâu nhưng… đằng nào thì đó cũng là vận mệnh không thể chối bỏ mà. Chỉ cần có thể tạo ra thời gian gặp gỡ em trai thế này thôi là chị đã thấy may mắn lắm rồi.”"
  },
  {
    "id": "[12]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Vận mệnh không thể chối bỏ, sao…”"
  },
  {
    "id": "[13]",
    "dst": "Mình phải trở nên hạnh phúc. Vì đó là sự chuộc lỗi ít ỏi duy nhất mình có thể làm cho Saya――vậy nên ở kiếp trước, tôi chỉ mải miết theo đuổi hạnh phúc vì mục đích đó."
  },
  {
    "id": "[14]",
    "dst": "Cảm giác muốn mưu cầu hạnh phúc vẫn không hề thay đổi ngay cả khi tôi đã được tái sinh."
  },
  {
    "id": "[15]",
    "dst": "Nhưng mà, vấn đề là."
  },
  {
    "id": "[16]",
    "dst": "Rốt cuộc hạnh phúc thực sự là gì――dạo gần đây tôi đã bắt đầu suy nghĩ như vậy."
  },
  {
    "id": "[17]",
    "dst": "Ở thế giới này không có lấy một cuốn hộ khẩu đàng hoàng, và những thứ như ảnh thẻ cũng hoàn toàn không tồn tại. Thế nên nếu trốn khỏi dinh thự rồi cải trang, thì việc trốn chạy khỏi gia tộc Granches cũng không phải là chuyện bất khả thi."
  },
  {
    "id": "[18]",
    "dst": "Ví dụ như xin làm đệ tử của một thương nhân nào đó, rồi dùng tri thức từ Trái Đất để sống tiếp cũng là một ý hay. Làm vậy thì chắc chắn tôi sẽ có thể trải qua những ngày tháng phong phú theo một cách nào đó."
  },
  {
    "id": "[19]",
    "dst": "Và tôi hoàn toàn có thể kéo theo Milly vào cuộc sống đó."
  },
  {
    "id": "[20]",
    "dst": "Nhưng còn chị Crealydil thì không thể. Bọn người trong gia tộc đời nào chịu để yên nếu chị Crealydil mất tích, và nói cho cùng thì chị ấy có thoát được khỏi dinh thự này đâu."
  },
  {
    "id": "[21]",
    "dst": "Một người chị bướng bỉnh nhưng lại dịu dàng, thỉnh thoảng vẫn lén đến đây chơi với tôi. Bỏ lại người chị Crealydil như thế để một mình trốn khỏi dinh thự."
  },
  {
    "id": "[22]",
    "dst": "Tôi có cảm giác rằng dù có đưa ra lựa chọn đó đi nữa, thì bản thân cũng chẳng thể hạnh phúc nổi."
  },
  {
    "id": "[23]",
    "dst": "Mọi người trên thế giới này ai nấy đều hạnh phúc――tôi không dám mong đến mức đó. Nhưng ít nhất, những người quan trọng đối với mình hãy luôn hạnh phúc――tôi cứ nghĩ vậy, thế nhưng…"
  },
  {
    "id": "[24]",
    "dst": "Dù cho chuyện của Milly có tính toán sao cho ổn thỏa đi chăng nữa, thì một bên là tôi, đứa con do người vợ lẽ sinh ra và đang bị hắt hủi, còn một bên là chị Crealydil, người sắp bị biến thành công cụ cho hôn nhân chính trị. Cứu được cả hai thì độ khó phải gọi là quá cao."
  },
  {
    "id": "[25]",
    "dst": "…Hay là mình thử nghiêm túc hướng đến mục tiêu cheat nội政 xem sao nhỉ."
  },
  {
    "id": "[26]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“A~ a~. Tại sao chuyện kết hôn thôi mà cũng không thể chọn người mình thích cơ chứ. Giá mà đối tượng kết hôn là em trai thì tốt biết mấy.”"
  },
  {
    "id": "[27]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“……………Hả? Đột nhiên cậu đang nói cái quái gì thế hả?”"
  },
  {
    "id": "[28]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Thì là vì thế đấy. Em trai chị vừa dịu dàng, đầu óc lại thông minh, cơ thể cũng được rèn luyện đúng không nào? Vẻ bề ngoài cũng đẹp trai nữa, đúng là em trai của chị có khác. Thế nên, giá mà đối tượng là em trai thì tốt biết bao.”"
  },
  {
    "id": "[29]",
    "speaker_to_listener": "Rion→Crealydil",
    "self_ref": "tôi",
    "addr_ref": "chị",
    "dst": "“Không không, dù là chỉ chung một nửa dòng máu đi chăng nữa, thì bọn mình rành rành là chị em ruột đấy nhé?”"
  },
  {
    "id": "[30]",
    "speaker_to_listener": "Crealydil→Rion",
    "self_ref": "chị",
    "addr_ref": "em",
    "dst": "“Chuyện đó thì chị biết là hôn nhân cận huyết không được nhìn nhận thiện cảm cho lắm chứ bộ? Nhưng mà, em đã nhìn thấy dù chỉ một ứng viên trong số các đối tượng hôn nhân chính trị của chị chưa hả?”"
  }
]

